//! Bench registry. Each bench module exposes `NAME` (CLI id) and
//! `run` (entry point). Add a bench by creating a module and
//! appending it to [`REGISTRY`].

pub mod ice_ps_1t;
pub mod ice_ps_2t;
pub mod ice_rr_1t;
pub mod ice_rr_2t;
pub mod min_now;
pub mod mpsc_1t;
pub mod mpsc_2t;
pub mod mpsc_2t_spin;
